<div class="flex min-h-screen bg-gray-50"><?php require __DIR__ . '/../../partials/admin-sidebar.php'; ?><main class="flex-1 px-8 py-8"><div class="max-w-5xl"><h1 class="font-display font-semibold text-2xl text-gray-900">Vouchers &amp; free shipping</h1><p class="text-sm text-gray-500 mt-1 mb-6">Create discounts customers can apply at checkout.</p><?php if (!empty($_SESSION['voucher_error'])): ?><p class="mb-4 rounded-lg bg-red-50 p-3 text-sm text-red-700"><?= htmlspecialchars($_SESSION['voucher_error']); unset($_SESSION['voucher_error']); ?></p><?php endif; ?><div class="grid lg:grid-cols-3 gap-6"><form method="POST" action="/admin/vouchers" class="bg-white border rounded-xl p-5 space-y-3"><h2 class="font-semibold">New voucher</h2><input required name="code" placeholder="Code e.g. LESS100" class="w-full border rounded-lg px-3 py-2 text-sm"><select name="discount_type" class="w-full border rounded-lg px-3 py-2 text-sm"><option value="fixed">Fixed amount off</option><option value="percent">Percentage off</option><option value="free_shipping">Free shipping</option></select><input name="discount_value" type="number" min="0" step="0.01" placeholder="Discount amount / percent" class="w-full border rounded-lg px-3 py-2 text-sm"><input name="minimum_order" type="number" min="0" step="0.01" placeholder="Minimum order (optional)" class="w-full border rounded-lg px-3 py-2 text-sm"><input name="maximum_discount" type="number" min="0" step="0.01" placeholder="Max discount (percent only)" class="w-full border rounded-lg px-3 py-2 text-sm"><label class="text-xs text-gray-500">Expiry (optional)<input name="ends_at" type="datetime-local" class="mt-1 w-full border rounded-lg px-3 py-2 text-sm"></label><button class="w-full bg-ink text-white rounded-lg py-2.5 text-sm font-semibold">Create voucher</button></form><div class="lg:col-span-2 bg-white border rounded-xl overflow-hidden"><div class="divide-y"><?php foreach ($vouchers as $voucher): ?><div class="p-4 flex items-center justify-between gap-4"><div><p class="font-mono font-semibold text-teal"><?= htmlspecialchars($voucher['code']) ?></p><p class="text-xs text-gray-500 mt-1"><?php if ($voucher['discount_type']==='free_shipping'): ?>Free shipping<?php elseif ($voucher['discount_type']==='percent'): ?><?= (float)$voucher['discount_value'] ?>% off<?php else: ?>₱<?= number_format((float)$voucher['discount_value'],2) ?> off<?php endif; ?> · Min. ₱<?= number_format((float)$voucher['minimum_order'],2) ?></p></div><form method="POST" action="/admin/vouchers/toggle"><input type="hidden" name="id" value="<?= (int)$voucher['id'] ?>"><button class="text-xs font-semibold <?= $voucher['is_active']?'text-teal':'text-gray-400' ?>"><?= $voucher['is_active']?'Active':'Inactive' ?></button></form></div><?php endforeach; ?><?php if (!$vouchers): ?><p class="p-6 text-sm text-gray-500">No vouchers yet.</p><?php endif; ?></div></div></div></div></main></div>
